// shell_bridge.test.ts — Exercises the actual WASM binary end-to-end.
//
// Loads shell.wasm in Node via wasm_exec.js, boots the shell with
// stub FS callbacks serving fixture data, feeds commands through
// wasmHandleInput, and asserts the write callback output matches the
// same expectations the Go-native test verifies.
//
// Fixtures are generated by `go generate ./shelltest/` — both the Go
// test and this test exercise the same cases, proving cross-environment
// parity between the CLI (native Go) and browser (Go→WASM→JS).

import { readFileSync } from 'node:fs'
import { resolve } from 'node:path'
import { describe, it, expect } from 'vitest'
import fixtures from './shell_fixtures.json'

// Load wasm_exec.js — it registers globalThis.Go
import './wasm_exec.js'

declare const Go: {
  new (): { importObject: WebAssembly.Imports; run(instance: WebAssembly.Instance): Promise<void> }
}

interface File {
  path: string
  content: string
  is_dir?: boolean
}

interface Case {
  name: string
  command: string
  // Pure-terminal contract: the client ships the line verbatim to the
  // executor. want_dispatch is the pipeline the WASM shell must send
  // (in its /api/shell/exec request) — it equals command, since nothing is
  // rendered or rewritten client-side.
  want_dispatch: string
}

interface Fixture {
  name: string
  files: File[]
  cases: Case[]
}

// Boot the WASM binary with given files as FS state. Returns a
// function to execute commands and read output.
async function bootShell(files: File[]): Promise<{
  exec: (command: string) => string
  dispatchedPipeline: () => string
  queryResult: (text: string, err: string, stack?: string[]) => Promise<string>
  completions: () => Array<[string, number]>
  setInput: (text: string) => void
  type: (data: string) => string
  settle: () => Promise<string>
  followRequested: () => boolean
  charts: () => Array<Record<string, unknown>>
}> {
  const wasmPath = resolve(__dirname, '../../public/shell.wasm')
  const wasmBuffer = readFileSync(wasmPath)

  const go = new Go()
  const { instance } = await WebAssembly.instantiate(wasmBuffer, go.importObject)
  void go.run(instance)

  let output = ''
  let dispatched = ''
  let follow = false
  // The one request in flight: the shell's POST to /api/shell/exec waits here
  // until the test answers it (queryResult) or the shell aborts it (Ctrl+C).
  let pending: { resolve: (r: Response) => void } | null = null
  ;(globalThis as Record<string, unknown>).fetch = (_url: string, init: RequestInit) =>
    new Promise<Response>((resolve, reject) => {
      const body = JSON.parse(init.body as string) as { pipeline: string; follow: boolean }
      // Pure-terminal: the shell ships every command line verbatim; capture
      // the pipeline so the test can assert ship-verbatim.
      dispatched = body.pipeline
      follow = body.follow
      pending = { resolve }
      init.signal?.addEventListener('abort', () => {
        pending = null
        reject(Object.assign(new Error('The operation was aborted.'), { name: 'AbortError' }))
      })
    })
  const settle = async () => {
    await new Promise(r => setTimeout(r, 60))
    return output
  }
  const completed: Array<[string, number]> = []
  const charts: Array<Record<string, unknown>> = []

  const callbacks = {
    write: (data: string) => { output += data },
    // The shell runs queries itself over fetch (stubbed below): it asks the
    // page for the API base and the headers of each request.
    apiBase: 'http://api.test',
    authHeaders: () => ({ Authorization: 'Bearer test' }),
    tourAdvance: () => {},
    notifyQuit: () => {},

    fsReadFile: (path: string) => {
      const f = files.find(file => file.path === path && !file.is_dir)
      if (!f) return { error: `not found: ${path}` }
      return { content: f.content }
    },
    fsWriteFile: (_path: string, _content: string) => ({}),
    fsReadDir: (path: string) => {
      // Root listing: return all mount prefixes (mirrors MountFS behavior).
      if (path === '/' || path === '') {
        return { entries: ['bin/', 'cron.d/', 'etc/', 'log/', 'tmp/'] }
      }
      // /log listing: return apps.
      if (path === '/log') {
        return { entries: ['myapp.log'] }
      }
      const prefix = path.endsWith('/') ? path : path + '/'
      const seen = new Set<string>()
      const entries: string[] = []
      for (const f of files) {
        if (!f.path.startsWith(prefix)) continue
        const rest = f.path.slice(prefix.length)
        if (!rest) continue
        const slashIdx = rest.indexOf('/')
        const name = slashIdx >= 0 ? rest.slice(0, slashIdx) : rest
        const isDir = slashIdx >= 0 || !!f.is_dir
        const entry = isDir ? name + '/' : name
        if (!seen.has(entry)) {
          seen.add(entry)
          entries.push(entry)
        }
      }
      entries.sort()
      return { entries }
    },
    fsRemove: (path: string) => {
      if (path.startsWith('/log')) return { error: 'read-only filesystem' }
      return {}
    },

    loadHistory: () => '',
    saveHistory: () => {},
    getUser: () => 'test',
    getCustomer: () => 'testco',
    fsGetCronSeries: () => ({ body: '{"granularity":"raw","points":[]}' }),
    onRangeChange: () => {},
    chartOpen: (spec: Record<string, unknown>) => { charts.push(spec) },
    builtinExecuted: () => {},
    // Host hook: every completed shell line, with its exit code.
    commandCompleted: (line: string, exitCode: number) => { completed.push([line, exitCode]) },
  }

  // wasmBoot is the bridge's boot entry; cmd/wasm/main.go registers the
  // default mode ("") with wasm.RegisterBoot.
  const wasmBoot = (globalThis as Record<string, unknown>).wasmBoot as
    (mode: string, instance: string, width: number, height: number, cb: typeof callbacks) => string
  const bootErr = wasmBoot('', '', 80, 24, callbacks)
  if (bootErr) throw new Error(bootErr)

  // Drain the initial render output.
  output = ''

  const wasmHandleInput = (globalThis as Record<string, unknown>).wasmHandleInput as
    (data: string) => void
  const g = globalThis as unknown as { wasmSetInput: (text: string) => void }

  return {
    exec: (command: string) => {
      output = ''
      dispatched = ''
      // Feed each character then press Enter (\r).
      wasmHandleInput(command + '\r')
      return output
    },
    dispatchedPipeline: () => dispatched,
    setInput: (text: string) => g.wasmSetInput(text),
    type: (data: string) => {
      output = ''
      wasmHandleInput(data)
      return output
    },
    settle,
    followRequested: () => follow,
    completions: () => completed.slice(),
    charts: () => charts.slice(),
    // Answer the shell's pending request the way the server does: an SSE
    // stream of row events (then the cwd it ended in, if any) and "done", or
    // a single error event.
    queryResult: async (text: string, err: string, stack?: string[]) => {
      output = ''
      const lines = text ? text.replace(/\n$/, '').split('\n') : []
      const events: unknown[] = err
        ? [{ type: 'error', message: err }]
        : [
            ...lines.map(raw => ({ type: 'line', data: { raw } })),
            ...(stack ? [{ type: 'cwd', stack }] : []),
            { type: 'done' },
          ]
      const sse = events.map(e => `data: ${JSON.stringify(e)}\n\n`).join('')
      pending?.resolve(new Response(sse, { status: 200, headers: { 'content-type': 'text/event-stream' } }))
      pending = null
      return settle()
    },
  }
}

// Pure-terminal parity: the WASM shell, like the native CLI, ships every
// command line verbatim to the executor (it renders no FS output itself).
// Each case asserts the pipeline the shell dispatched equals want_dispatch.
// Listing/read/permission semantics are the server's job, covered by the
// coordinator + integration suites.
for (const fixture of fixtures as Fixture[]) {
  describe(fixture.name, () => {
    for (const tc of fixture.cases) {
      it(tc.name, async () => {
        const shell = await bootShell(fixture.files)
        shell.exec(tc.command)
        expect(shell.dispatchedPipeline()).toBe(tc.want_dispatch)
      })
    }
  })
}

// Dirstack courier through the real wasm: the shell sends its directory stack
// with each request, and the stack a shipped segment returns (the "cwd" event)
// is applied before the redraw, so the prompt shows the new cwd.
describe('dirstack courier (wasm)', () => {
  it('redraws the prompt with the cwd a shipped segment left behind', async () => {
    const shell = await bootShell([])
    // cd itself is the shell's own and is never shipped.
    shell.exec('tail /log/a/b/main.log')
    expect(shell.dispatchedPipeline()).toBe('tail /log/a/b/main.log')
    const redraw = await shell.queryResult('', '', ['/tmp'])
    expect(redraw).toContain('/tmp')
  })
})

// Lesson/progress tracking is driven from the browser: the shell core
// publishes CommandCompleted for every line, and the wasm bridge forwards
// it to the host as commandCompleted(line, exitCode). That covers inline
// builtins (`history`) and lines whose pipe stages the client handles
// itself, which the server's exec-path never sees in full.
describe('commandCompleted host hook (wasm)', () => {
  const settle = () => new Promise(r => setTimeout(r, 30))

  it('reports an inline builtin with exit 0', async () => {
    const shell = await bootShell([])
    shell.exec('history')
    await settle()
    expect(shell.completions()).toContainEqual(['history', 0])
  })

  it('reports a dispatched line with the full text once its result arrives', async () => {
    const shell = await bootShell([])
    shell.exec('tail /log/a/b/main.log | grep ERROR')
    await shell.queryResult('', '')
    expect(shell.completions()).toContainEqual(['tail /log/a/b/main.log | grep ERROR', 0])
  })

  it('reports a failed line with a non-zero exit code', async () => {
    const shell = await bootShell([])
    shell.exec('cat /log/nope.log')
    await shell.queryResult('', 'boom')
    const done = shell.completions().find(([line]) => line === 'cat /log/nope.log')
    expect(done).toBeDefined()
    expect(done![1]).not.toBe(0)
  })
})

// The tour prefills the next command with setInput. Pressing Enter runs it;
// typing instead replaces it rather than appending (OB-6).
describe('prefilled input (wasm)', () => {
  it('runs an untouched prefill verbatim on Enter', async () => {
    const shell = await bootShell([])
    shell.setInput('cat /etc/notify.yaml')
    shell.type('\r')
    expect(shell.dispatchedPipeline()).toBe('cat /etc/notify.yaml')
  })

  it('is replaced, not appended to, by typing', async () => {
    const shell = await bootShell([])
    shell.setInput('cat /etc/notify.yaml')
    shell.exec('ls /tmp')
    expect(shell.dispatchedPipeline()).toBe('ls /tmp')
  })
})

// Ctrl+C stops a tail: the shell aborts the follow's fetch and says so once
// (a dim ^C). The abort must not surface as an error (OB-8).
describe('tail -f stop (wasm)', () => {
  it('prints ^C once and no error when Ctrl+C aborts the stream', async () => {
    const shell = await bootShell([])
    shell.exec('tail -f /log/a/b/main.log')
    expect(shell.followRequested()).toBe(true)
    shell.type('\x03')
    const out = await shell.settle()
    expect(out.split('^C').length - 1).toBe(1)
    expect(out).not.toContain('canceled')
    expect(out).not.toContain('cannot reach')
  })
})

// `... | chart` computes its plot in Go (flags applied) and hands the browser
// finished series, not the raw rows (OB-5).
describe('pipe-form chart (wasm)', () => {
  it('opens the chart with the bucketed series', async () => {
    const shell = await bootShell([])
    shell.exec('tail /log/a/b/main.log | chart -x 1 --bucket 5m')
    // Rows inside the shell's default 1d.. range, in two 5-minute buckets.
    const bucket = Math.floor(Date.now() / 300_000) * 300_000 - 3_600_000
    const at = (ms: number) => new Date(bucket + ms).toISOString().replace(/\.\d+Z$/, 'Z')
    await shell.queryResult([
      `${at(1_000)} ERROR a`,
      `${at(160_000)} ERROR b`,
      `${at(420_000)} ERROR c`,
    ].join('\n') + '\n', '')
    const [spec] = shell.charts()
    expect(spec).toBeDefined()
    const plot = JSON.parse(spec.plot as string)
    expect(plot.timeX).toBe(true)
    const ys = plot.series[0].points.map((p: { y: number }) => p.y)
    expect(ys.filter((y: number) => y > 0)).toEqual([2, 1])
    // Zero-filled across the whole day, and the axis spans it.
    expect(ys.length).toBeGreaterThan(280)
    expect(plot.xMax - plot.xMin).toBeGreaterThanOrEqual(86_400)
  })
})
